function testPublic(t,teacher=false){return {...testSummary(t),questions:(t.questions||[]).map(q=>{const rawImage=q.image||'',rawNoteImage=q.noteImage||'';const b={id:q.id,type:q.type,text:q.text||'',image:questionImagePublic(rawImage,t.id),imageRef:teacher?rawImage:'',options:(q.options||[]).map(o=>({id:o.id,text:o.text||'',image:questionImagePublic(o.image,t.id),imageRef:teacher?(o.image||''):''}))};return teacher?{...b,note:q.note||'',noteImage:questionImagePublic(rawNoteImage,t.id),noteImageRef:rawNoteImage,noteVideoId:q.noteVideoId||'',noteAudioId:q.noteAudioId||'',correctOptionId:q.correctOptionId||'',correctOptionIds:Array.isArray(q.correctOptionIds)?q.correctOptionIds:(q.correctOptionId?[q.correctOptionId]:[]),correctAnswer:typeof q.correctAnswer==='boolean'?q.correctAnswer:null}:b})}}
function activitiesFor(id){return db.activities.filter(a=>a.studentId===id&&a.type!=='login'&&a.type!=='logout'&&a.type!=='page_view').sort((a,b)=>b.createdAt-a.createdAt)}
function sanitizeImage(value,label,maxBytes=2*1024*1024){
  const image=String(value||'').trim();
  if(!image)return '';
  if(/^tg:/i.test(image)){
    const id=image.slice(3).trim();
    if(!isTelegramFileId(id))throw new Error(`${label} Telegram File ID غير صالح`);
    return `tg:${id}`;
  }
  if(!/^data:image\/(png|jpeg|jpg|webp);base64,/i.test(image))throw new Error(`${label} غير صالحة`);
  if(Buffer.byteLength(image,'utf8')>maxBytes)throw new Error(`${label} أكبر من 2MB`);
  return image;
}
function questionImagePublic(value,testId){
  const image=String(value||'');
  if(!image)return '';
  if(/^tg:/i.test(image))return `/telegram-question-media/${encodeURIComponent(testId)}/${encodeURIComponent(image.slice(3))}`;
  return image;
}
function sanitizeQuestions(input){
  if(!Array.isArray(input)||input.length<1||input.length>100)return {ok:false,error:'عدد الأسئلة يجب أن يكون بين 1 و100'};
  try{
    const out=[];
    for(let i=0;i<input.length;i++){
      const q=input[i]||{};
      const type=q.type==='truefalse'?'truefalse':'choice';
      const text=String(q.text||'').trim();
      const image=sanitizeImage(q.image,`صورة السؤال ${i+1}`);
      if(!text&&!image)return {ok:false,error:`السؤال ${i+1} يجب أن يحتوي نصاً أو صورة واحدة على الأقل`};
      const note=String(q.note||'').trim().slice(0,1000);
      const noteImage=sanitizeImage(q.noteImage,`صورة ملاحظة السؤال ${i+1}`);
      const noteVideoId=String(q.noteVideoId||'').trim();
      const noteAudioId=String(q.noteAudioId||'').trim();
      if(type==='truefalse'){
        if(typeof q.correctAnswer!=='boolean')return {ok:false,error:`حدد إجابة السؤال ${i+1}`};
        out.push({id:String(q.id||uid('q')),type,text,image,note,noteImage,noteVideoId,noteAudioId,options:[],correctOptionId:'',correctAnswer:q.correctAnswer});
      }else{
        const rawOpts=Array.isArray(q.options)?q.options:[];
        const opts=rawOpts.slice(0,4).map((o,j)=>({id:String(o.id||uid('op')),text:String(o.text||'').trim(),image:sanitizeImage(o.image,`صورة الاختيار ${i+1}-${j+1}`)}));
        if(opts.length<2||opts.some(o=>!o.text&&!o.image))return {ok:false,error:`السؤال ${i+1} يحتاج من 2 إلى 4 اختيارات، وكل اختيار يحتوي نصاً أو صورة`};
        const correctIds=[...(Array.isArray(q.correctOptionIds)?q.correctOptionIds:(q.correctOptionId?[q.correctOptionId]:[]))].map(String).filter((v,i,a)=>v&&a.indexOf(v)===i);
        if(!correctIds.length||correctIds.some(id=>!opts.some(o=>o.id===id)))return {ok:false,error:`حدد إجابة صحيحة واحدة على الأقل للسؤال ${i+1}`};
        out.push({id:String(q.id||uid('q')),type,text,image,note,noteImage,noteVideoId,noteAudioId,options:opts,correctOptionId:correctIds[0],correctOptionIds:correctIds,correctAnswer:null});
      }
    }
    return {ok:true,value:out};
  }catch(e){return {ok:false,error:e.message||'بيانات الأسئلة غير صالحة'}}
}
function retakeTicket(studentId,testId){return db.testRetakes.find(x=>x.studentId===studentId&&x.testId===testId&&!x.usedAt)}
